    game.settings.get(
      MODULE_ID,
      "presentationMode"
    );

  return value === "sidebar"
    ? "sidebar"
    : "window";
}


function setFrameConnPresentationModeSetting(
  mode
) {
  const normalizedMode =
    mode === "sidebar"
      ? "sidebar"
      : "window";

  return game.settings.set(
    MODULE_ID,
    "presentationMode",
    normalizedMode
  );
}


